<?php require __DIR__.'/config.php';require_admin();$m=$_SERVER['REQUEST_METHOD']??'GET';if($m==='GET'){$s=$pdo->query("SELECT o.id,o.order_code,o.total,o.subtotal,o.delivery_fee,o.delivery_address,o.status,o.order_type,o.created_at,u.full_name,u.email,p.method payment_method,p.status payment_status FROM orders o JOIN users u ON u.id=o.customer_id LEFT JOIN payments p ON p.order_id=o.id ORDER BY o.id DESC");$rows=$s->fetchAll();foreach($rows as &$o){$q=$pdo->prepare('SELECT product_name,quantity FROM order_items WHERE order_id=?');$q->execute([$o['id']]);$o['items']=$q->fetchAll();}json_out(['orders'=>$rows]);}if($m==='PATCH'){$d=body_json();$id=(int)($d['id']??0);$status=(string)($d['status']??'');$allowed=['Order Placed','Confirmed','Preparing','Ready for Pickup','Out for Delivery','Completed','Cancelled'];if($id<1||!in_array($status,$allowed,true))json_out(['error'=>'Invalid order or status.'],422);$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$status,$id]);json_out(['ok'=>true]);}json_out(['error'=>'Method not allowed.'],405);?>